    "src/main/java/application/CargarParametrosNegocio.java": "package application;

import domain.Parametro;
import domain.ParametroRepository;
import domain.ParametrosNegocio;

/**
 * Caso de uso: carga_parametros_negocio.
 * Inserta en ls_parametros todos los parámetros del catálogo (02_parametros.sql:10-36).
 * El COMMIT (línea 38) es control transaccional de infraestructura y no se modela.
 */
public final class CargarParametrosNegocio {

    private final ParametroRepository repositorio;

    public CargarParametrosNegocio(ParametroRepository repositorio) {
        this.repositorio = repositorio;
    }

    /** @return cantidad de filas insertadas */
    public int ejecutar() {
        int insertadas = 0;
        for (Parametro p : ParametrosNegocio.catalogo()) {
            repositorio.insertar(p);
            insertadas++;
        }
        return insertadas;
    }
}
