import java.util.ArrayList;
import java.util.List;

/** Adaptador en memoria del puerto ParametroRepository (cargado desde "_tablas"). */
final class InMemoryParametroRepository implements ParametroRepository {

    private final List<Parametro> filas = new ArrayList<>();

    @Override
    public void insertar(Parametro parametro) {
        filas.add(parametro);
    }

    @Override
    public List<Parametro> listar() {
        return List.copyOf(filas);
    }
}
