    "src/main/java/app/Entry.java": "package app;

import application.CargarParametrosNegocio;
import domain.Parametro;
import domain.ParametroRepository;

import java.math.BigDecimal;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** Punto de entrada de verificación: sin lógica de negocio, delega en la capa de aplicación. */
public final class Entry {

    private Entry() {
    }

    @SuppressWarnings("unchecked")
    public static Object run(Map<String, Object> input) {
        ParametroRepository repo = new InMemoryParametroRepository();

        // Estado inicial de la tabla (si el caso lo trae)
        if (input != null && input.get("_tablas") instanceof Map<?, ?> tablas) {
            for (Map.Entry<?, ?> t : tablas.entrySet()) {
                if ("ls_parametros".equalsIgnoreCase(String.valueOf(t.getKey()))
                        && t.getValue() instanceof List<?> filas) {
                    for (Object f : filas) {
                        if (f instanceof Map<?, ?> fila) {
                            repo.insertar(aParametro((Map<String, Object>) fila));
                        }
                    }
                }
            }
        }

        new CargarParametrosNegocio(repo).ejecutar();

        // El contrato no declara salidas: el resultado es un mapa vacío.
        return new LinkedHashMap<String, Object>();
    }

    private static Parametro aParametro(Map<String, Object> fila) {
        Object num = valor(fila, "valor_numerico");
        Object txt = valor(fila, "valor_texto");
        Object desc = valor(fila, "descripcion");
        return new Parametro(
                String.valueOf(valor(fila, "codigo")),
                num == null ? null : new BigDecimal(String.valueOf(num)),
                txt == null ? null : String.valueOf(txt),
                desc == null ? null : String.valueOf(desc));
    }

    private static Object valor(Map<String, Object> fila, String columna) {
        for (Map.Entry<String, Object> e : fila.entrySet()) {
            if (e.getKey().equalsIgnoreCase(columna)) {
                return e.getValue();
            }
        }
        return null;
    }
}
