    "src/main/java/infrastructure/JdbcParametroRepository.java": "package infrastructure;

import domain.Parametro;
import domain.ParametroRepository;
import org.springframework.jdbc.core.JdbcTemplate;

import java.util.List;

/** Adaptador Spring JDBC del puerto ParametroRepository (base de datos real). */
public class JdbcParametroRepository implements ParametroRepository {

    private final JdbcTemplate jdbc;

    public JdbcParametroRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    @Override
    public void insertar(Parametro p) {
        jdbc.update("INSERT INTO ls_parametros VALUES (?, ?, ?, ?)",
                p.codigo(), p.valorNumerico(), p.valorTexto(), p.descripcion());
    }

    @Override
    public List<Parametro> listar() {
        return jdbc.query(
                "SELECT codigo, valor_numerico, valor_texto, descripcion FROM ls_parametros",
                (rs, i) -> new Parametro(
                        rs.getString("codigo"),
                        rs.getBigDecimal("valor_numerico"),
                        rs.getString("valor_texto"),
                        rs.getString("descripcion")));
    }
}
