    "src/main/java/infrastructure/ParametrosConfig.java": "package infrastructure;

import application.CargarParametrosNegocio;
import domain.ParametroRepository;
import org.springframework.boot.CommandLineRunner;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.support.TransactionTemplate;

/** Configuración Spring: cablea puerto, caso de uso y ejecución de la carga inicial. */
@Configuration
public class ParametrosConfig {

    @Bean
    ParametroRepository parametroRepository(JdbcTemplate jdbc) {
        return new JdbcParametroRepository(jdbc);
    }

    @Bean
    CargarParametrosNegocio cargarParametrosNegocio(ParametroRepository repo) {
        return new CargarParametrosNegocio(repo);
    }

    /** El COMMIT legacy (línea 38) se resuelve con la transacción de Spring. */
    @Bean
    CommandLineRunner cargaInicial(CargarParametrosNegocio caso, TransactionTemplate tx) {
        return args -> tx.executeWithoutResult(status -> caso.ejecutar());
    }
}
